    const txt = t.here ? t.label : `${t.label} ${Math.round(d)} m`; const sp = el.querySelector('span'); if (sp.textContent !== txt) sp.textContent = txt;
    const cam = this.h.camera, fw = V(); cam.getWorldDirection(fw);
    const a = Math.atan2(t.p.x - p.x, -(t.p.z - p.z)) - Math.atan2(fw.x, -fw.z);
