    if (this.simple) {
      if (k === 'relief' && !now) {   // 待たせない: 呼ばれるまで自由にしていてよい
        this.reliefCall = true;
        if (!this._pcListen && typeof window !== 'undefined') { this._pcListen = true; window.addEventListener('pitcherchange', (e) => this.onPitcherChange(e.detail || {})); }
        this.say('投手交代の時に呼びます', null, { must: true, ms: 2000 }); return;
      }
      def = { ...def, dur: JOBS_SIMPLE[k] || 600 };
    }
    if (this.job) this.endJob(true);
    this.drop(true);
    this.job = { def, k, t: 0, earned: 0, n: 0, d: {} };
    this.wearBackup = { ...this.wear }; this.jobUni = def.uni; this.applyWear();
    const H = this.h, j = this.job;
