    const fromDesk = this.jobDesk && Math.hypot(this.jobDesk.x - H.player.pos.x, this.jobDesk.z - H.player.pos.z) < 6;
    if (fromDesk && !['ball', 'ground', 'mogiri', 'goods'].includes(k)) this.jobPost(k);
    if (k === 'beer') { j.d.cups = 10; j.d.callers = []; this.makeTank(); }
    if (k === 'shop') { const st = this.nearStall() || this.jobStall(false) || (this.walkers() && this.walkers().stalls.concat(this.wagons || [])[0]); if (st) { const fx = st.fx || 0, fz = st.fz || 1; H.placeAt(st.x + fx * 1.8, st.z + fz * 1.8, st.x, st.z, st.y + 1.3, st.y + 2); } this.shopGame(); }
    if (k === 'ball') { const sp = this.spot; if (sp) { const q = V(-sp.x, sp.y, sp.z); H.placeAt(q.x, q.z, 0, -20, 1.0, 3); } j.d.next = 4; }
    if (k === 'mogiri') { const pl = this.ticketPlan(); j.d.guests = []; j.d.next = 0.5; if (pl) { const q = pl.out.clone().addScaledVector(pl.outward, -1.2); j.d.post = q; j.d.pl = pl; H.placeAt(q.x, q.z, q.x + pl.outward.x * 10, q.z + pl.outward.z * 10, q.y + 1.5, q.y + 2); } }
    if (k === 'goods') { const L = (this.outStores || []).concat(this.simple ? (this.mopen || []) : (this.mshops || [])).filter((x) => x.kind === 'グッズ' || (this.simple && kindOf(this.stallMenu(x).title) === 'goods')); const q = this.jobDesk || H.player.pos; const st = L.length ? L.reduce((a, b) => (Math.hypot(a.x - q.x, a.z - q.z) <= Math.hypot(b.x - q.x, b.z - q.z) ? a : b)) : null; if (st) { const fx = st.fx || 0, fz = st.fz || 1; H.placeAt(st.x + fx * 1.8, st.z + fz * 1.8, st.x, st.z, st.y + 1.3, st.y + 2); } this.shopGame(['megaphone', 'towel', 'plush', 'keychain', 'minibat', 'kinen', 'balloon'], 180); }
    if (k === 'clean') { j.d.trash = []; j.d.bag = []; this.makeBins(); }
    if (k === 'guide') { j.d.guest = null; }
    if (k === 'cheer') this.hold('megaphone');
    if (k === 'ground') { const v = this.vehicles.find((x) => x.kind === 'tractor'); if (v) { if (!v.garage) this.goSpot(); else { v.g.position.copy(v.garage.park); v.yaw = v.garage.yaw; v.g.rotation.y = v.yaw; v.hide = false; v.g.visible = true; } this.dragDoneT = null; this.enterVehicle(v); if (v.garage) { this.garageMove(v, true); this.say('シャッターが開いて、整備の車でグラウンドへ', '内野をならしたら、出入口のシャッターの前で降りると車庫へ戻る'); } } }
    if (k === 'relief') this.startRelief();
