    const ray = new THREE.Ray(from, d), hit = this.h.world.bvh.raycastFirst(ray, THREE.DoubleSide, 0, L);
    if (hit) want.copy(from).addScaledVector(d, Math.max(0.8, hit.distance - 0.3));
    c.position.copy(want); c.lookAt(P.x, P.y + 1.4, P.z);
