    const n8 = new Map(), n20 = new Map(); for (const q of all) { if (q === s || q._rsOf !== R || !(q._rs >= 0) || Math.abs(q.y - s.y) > 3) continue; const d = Math.hypot(q.x - s.x, q.z - s.z); if (d < 8) n8.set(q._rs, (n8.get(q._rs) || 0) + 1); else if (d < 20) n20.set(q._rs, (n20.get(q._rs) || 0) + 1); }
    this._rsN = (this._rsN || 0) + 1; const N = cand.length, M = R.shops.length; let k = -1, bs = 1e18;
    for (let t = 0; t < N; t++) { const c = cand[(this._rsN + t) % N], v = (n8.get(c) || 0) * 1e6 + (n20.get(c) || 0) * 1.5 * M + (R._cnt[c] + 1) / R._p[c]; if (v < bs) { bs = v; k = c; } }
