      const own = new Set(R.shops.flatMap((q) => q.items)), rk = (id) => (!/^[a-z]{2}_/.test(id) || own.has(id) ? 0 : 1);   // 定番の品・この球場の品を先に(ほかの球場の名前の付いた品は、それしか無い時だけ)
