    this.realWeights(R); s._rsOf = R; s._rmSig = this.shopSigns; s._rs = -1; s._rm = null;
    const seen = this.seenName(s);
    if (seen) { s._rm = this.kbNameMenu(seen, s); return s._rm; }   // 11/22 看板: 同じ店名の店は同じ品書き(模型に焼き込まれた品書きの板をその品で描き直すので)
    if (s.kind === '自動販売機') return null;
