      const o = look.clone().addScaledVector(d, 0.6), hit = bvh.raycastFirst(new THREE.Ray(o, d), THREE.DoubleSide, 0, 4.4);
      const L = hit ? hit.distance + 0.6 - 0.3 : 5;
