      let sum = 0, best = -1, fx = 0, fz = 1;
      for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; ray.origin.set(n.x, n.y + 1.0, n.z); ray.direction.set(Math.sin(a), 0, Math.cos(a)); const h = bvh.raycastFirst(ray, THREE.DoubleSide, 0, 8); const L = h ? h.distance : 8; sum += L; if (L > best) { best = L; fx = Math.sin(a); fz = Math.cos(a); } }
      if (best < 5 || sum < 34) continue;
