    const vis = []; this.scene.traverse((o) => { if (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh && o.geometry && !/^(crowd|walkers|freeplay)/.test((o.parent && o.parent.name) || '') && !/crowd|ivy|sky|glow/i.test(o.name || '')) { const bb = new THREE.Box3().setFromObject(o); if (bb.isEmpty() || bb.getSize(V()).length() > 2000) return; vis.push({ o, bb }); } });
    const rc = new THREE.Raycaster(), sph = new THREE.Sphere();
