      let sum = 0, best = -1, fx = 0, fz = 1, back = 9;
      for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; rc.set(V(n.x, n.y + 1.0, n.z), V(Math.sin(a), 0, Math.cos(a))); rc.far = 8; const h = rc.intersectObjects(near, false)[0]; const L = h ? h.distance : 8; sum += L; if (L > best) { best = L; fx = Math.sin(a); fz = Math.cos(a); } }
      rc.set(V(n.x, n.y + 1.0, n.z), V(-fx, 0, -fz)); rc.far = 3; if (rc.intersectObjects(near, false)[0]) back = 0;
      if (best >= 5 && sum >= 30 && back > 0) checked.push({ n, sum, fx, fz });
