    const avoid = [].concat(pass, (W.stalls || []).map((q) => V(q.x, q.y, q.z)), (this.mopen || []).map((q) => V(q.x, q.y, q.z)), (this.outStores || []).map((q) => V(q.x, q.y, q.z)), (this.eatSpots || []).map((e) => e.p), (this.gateSpots || []).map((g) => g.o), (this.wagons || []).map((q) => V(q.x, q.y, q.z)));   // 11/21 ワゴンの前も避ける
    // 模型の売店の面(看板・カウンター・メニュー・自販機)の前には置かない: その材質の形だけを集めて、置く前に壁の所を光線で確かめる
