        const hit = bvh.raycastFirst(new THREE.Ray(V(x, fy + 1.2, z), V(dx, 0, dz)), THREE.DoubleSide, 0, 1.2); if (!hit) continue;
        if (!sp.toiletOpen && !bvh.raycastFirst(new THREE.Ray(V(x, fy + 2.2, z), V(0, 1, 0)), THREE.DoubleSide, 0, 3.3)) continue;
        let flat = true; for (const k of [0.8, 1.6, 2.4]) { const q = down(x - dx * k, z - dz * k, fy); if (q === null || Math.abs(q - fy) > 0.15) { flat = false; break; } } if (!flat) continue;
        const f = V(-dx, 0, -dz);
        if (bvh.raycastFirst(new THREE.Ray(V(hit.point.x + f.x * 0.2, fy + 1.2, hit.point.z + f.z * 0.2), f), THREE.DoubleSide, 0, 2.6)) continue;
        if (avoid.some((q) => Math.hypot(q.x - x, q.z - z) < 4 && Math.abs(q.y - fy) < 2.5)) continue;
        if (this.toilets.some((t) => Math.hypot(t.p.x - x, t.p.z - z) < 15 && Math.abs(t.p.y - fy) < 2)) continue;
        if (isShop(x, fy, z, dx, dz)) continue;
