    if (this.booth && this.boothFront) { const d = Math.hypot(this.boothFront.x - p.x, this.boothFront.z - p.z); if (d < 3.2 && Math.abs(this.boothFront.y - p.y) < 2) consider(d, { label: this.ticket ? 'チケット売り場(買い直す)' : 'チケットを買う', run: () => this.openTicket() }); }
