    if (((this._wl = (this._wl || 0) + 1) % 20) === 0) {
      const Wt = H.watch(), low = !!(Wt && Wt.on) && innerWidth <= 480, el = this.elWallet;
      el.classList.toggle('low', low);
      if (low) { let bot = 0; for (const e of [document.getElementById('board'), document.getElementById('runMap')]) { if (e) { const r = e.getBoundingClientRect(); if (r.height > 0 && r.left < innerWidth / 2) bot = Math.max(bot, r.bottom); } } el.style.top = `${Math.round(bot + 6)}px`; }
      else el.style.top = '';
    }
    { const cl = H.curLabel(), slideOk = !this.simple && !this.held && H.input.run && H.player.onGround && !this.slide && (H.player.speedNow || 0) > 5;
      this.elUse.classList.toggle('hide', this.simple || !(touch && mode === 'walk' && ((this.held && cl && cl !== this.useLabel()) || slideOk)));
      if (slideOk && this.elUse.textContent !== 'すべる') this.elUse.textContent = 'すべる'; }   // 緑のボタンが別の物(乗る・店…)の時だけ出す
    if (this.held) { const l = this.useLabel() || '使う'; if (this.elUse.textContent !== l) this.elUse.textContent = l; }
