    this.elQuit.classList.toggle('hide', !(this.simple && (this.job || this.reliefCall)));
    if (this.simple) { const it = this.held && ITEMS[this.held.id], food = !!(it && (it.use === 'eat' || it.use === 'drink')), walk = mode === 'walk' || mode === 'sit', nb = this.bagCount(), show = walk && !this.sheetOn && !this.job && (food || (!this.held && nb > 0));
      const dupE = touch && food && /^(食べる|飲む)$/.test(H.curLabel() || '');   // スマホの右下の緑のボタンが既に「食べる」なら、真ん中は「しまう」だけ
      const st = show ? `${food ? 1 : 0}${it ? it.use : ''}${nb}${dupE ? 'd' : ''}` : 'x'; if (this._handSt !== st) { this._handSt = st; this.elHand.classList.toggle('hide', !show); const E = this.elHand.querySelector('.eat'), S2 = this.elHand.querySelector('.stow'), B = this.elHand.querySelector('.bag');
        E.style.display = food && !dupE ? '' : 'none'; S2.style.display = food ? '' : 'none'; B.style.display = 'none'; E.textContent = it && it.use === 'drink' ? '飲む' : '食べる'; this.elHand.classList.toggle('hide', !(show && food)); }
      { const bs = walk && !this.sheetOn && !this.job && nb > 0 ? String(nb > 99 ? '99+' : nb) : ''; if (this._bagSt !== bs) { this._bagSt = bs; this.elBag.classList.toggle('hide', !bs); this.elBag.querySelector('.n').textContent = bs; } } }
    if (this.reliefCall && !this.job && this.simple) { this.elBar.classList.remove('hide'); if (this.elBar.textContent !== 'リリーフカー 待機中') this.elBar.textContent = 'リリーフカー 待機中'; }
